from mk import *
import math
h = 0.6 * (1 - math.cos(math.radians(12))); Ek = 5 * 10 * h; V = math.sqrt(2 * 10 * h); v0 = 5 * V / 0.015; loss = 0.5 * 0.015 * v0 ** 2 - Ek

def fig():
    g = Fig(560, 230, "מטוטלת בליסטית בשלושה שלבים: קליע m1 במהירות v0 נע לעבר גוף m2 שתלוי על חוט באורך ℓ; הקליע נעצר בגוף בנקודה A; הגוף עם הקליע עולה עד הנקודה B, שבה החוט נוטה בזווית תטא מהאנך")
    for ox, lab in ((450, "שלב ראשון"), (280, "שלב שני"), (100, "שלב שלישי")):
        g.ceiling(ox - 25, ox + 25, 40); g.heb(ox, 24, lab)
    g.line(450, 40, 450, 150, width=1.5); g.text(458, 100, "ℓ", anchor="start"); g.block(450, 164, 34, 26, "m₂"); g.circle(520, 164, 3, fill="var(--d-label)"); g.arrow(514, 156, 496, 156, "v₀", lx=520, ly=148, anchor="start"); g.text(520, 186, "m₁")
    g.line(280, 40, 280, 150, width=1.5); g.block(280, 164, 34, 26, "A"); g.text(280, 196, "m₁+m₂")
    a = math.radians(30)
    bx, by = 100 - 110 * math.sin(a), 40 + 110 * math.cos(a)
    g.line(100, 40, bx, by, width=1.5); g.block(bx, by + 10, 30, 22, "B", angle=30)
    g.line(100, 40, 100, 160, stroke="var(--d-dim)", width=1, dash="3 3"); g.angle(100, 40, 30, 240, 270, "θ", lr=44)
    return g

E(id="bagrut-2018-q4", year=2018, label="2018 שאלה 4", topic="momentum", sub="mom-collisions", diff=3, fig=fig,
  stem=r"עד המאה השמונה-עשרה לא היה אפשר למדוד את מהירותם של גופים מהירים כגון קליע של רובה. בשנת $1742$ המציא המדען האנגלי בנג'מין רובינס שיטה למדידת מהירותם של קליעים באמצעות מטוטלת בליסטית. בשלב הראשון נורה קליע שמסתו $m_1$ לכיוון גוף שמסתו $m_2$, שתלוי על חוט שאורכו $\ell$. בשלב השני הקליע פוגע בגוף בנקודה $A$ במהירות אופקית שגודלה $v_0$, חודר לגוף ונעצר בתוכו. משך זמן החדירה של הקליע לתוך הגוף קצר ביותר, ולכן תזוזת הגוף בזמן זה ניתנת להזנחה. בשלב השלישי הגוף (עם הקליע בתוכו) עולה עד לנקודה $B$ ושם נעצר רגעית. בנקודה זו זווית הסטייה של החוט מהאנך היא $\theta$. יש להזניח את התנגדות האוויר ואת מסת החוט. הסעיפים מתייחסים למערכת גוף + קליע.",
  parts=[
    P("א", r"קבע אם התנע והאנרגיה המכנית נשמרים בפרק הזמן שבין רגע פגיעת הקליע בגוף ועד לעצירתו בתוך הגוף. הסבר את קביעותיך.", OPEN, ["principle"], [
        S(r"תנע", r"בזמן הקצר הזה אין כוח חיצוני אופקי משמעותי: נשמר", r"\Delta p_x = 0"),
        S(r"אנרגיה מכנית", r"התנגשות פלסטית: חלק גדול הופך לחום ולעיוות", r"\Delta E < 0"),
    ], r"התנע נשמר, האנרגיה המכנית לא"),
    P("ב", r"קבע אם התנע והאנרגיה המכנית נשמרים בפרק הזמן שבין תחילת תנועת הגוף (עם הקליע) ועד לעצירתו הרגעית בנקודה $B$. הסבר את קביעותיך.", OPEN, ["principle"], [
        S(r"תנע", r"פועלים כובד ומתיחות, והשקול לא אפס: לא נשמר", r"\textstyle\sum F \ne 0"),
        S(r"אנרגיה מכנית", r"רק הכובד עושה עבודה, והמתיחות ניצבת לתנועה: נשמרת", r"W_T = 0"),
    ], r"התנע לא נשמר, האנרגיה המכנית נשמרת", key=r"תנע לא נשמר ; אנרגיה מכנית נשמרת"),
    P("ג", r"נתוני המערכת: מסת הקליע $m_1 = 0.015\,\text{kg}$, מסת הגוף $m_2 = 4.985\,\text{kg}$, אורך החוט $\ell = 0.6\,\text{m}$, זווית הסטייה המרבית של החוט $\theta = 12^\circ$. חשב את האנרגיה הקינטית של המערכת, מיד אחרי שהגוף (עם הקליע בתוכו) התחיל את תנועתו בנקודה $A$.", num(Ek, "J"), ["principle"], [
        S(r"הגובה שהגוף עולה", r"גיאומטריה של מטוטלת", r"h = \ell(1 - \cos\theta) = 0.6(1 - \cos 12^\circ) \approx 0.0131\,\text{m}"),
        S(r"שימור אנרגיה", r"מסה כוללת $5\,\text{kg}$", r"E_k = 5 \cdot 10 \cdot 0.0131 \approx 0.656\,\text{J}"),
    ], r"$\approx 0.656\,\text{J}$", key=r"Ek=0.656 J"),
    P("ד", r"חשב את $v_0$, מהירות הקליע ברגע פגיעתו בגוף.", num(v0, "m/s"), ["principle"], [
        S(r"מהירות הגוף אחרי ההתנגשות", r"מהאנרגיה הקינטית", r"V = \sqrt{\frac{2E_k}{5}} \approx 0.512\,\text{m/s}"),
        S(r"שימור תנע בהתנגשות", r"הקליע נעצר בגוף", r"0.015\,v_0 = 5 \cdot 0.512 \Rightarrow v_0 \approx 170.7\,\text{m/s}"),
    ], r"$\approx 170.7\,\text{m/s}$", key=r"v0=170.7 m/s"),
    P("ה", r"חשב את האנרגיה המכנית ש\"אבדה\" בגלל החיכוך.", num(loss, "J"), ["principle"], [
        S(r"אנרגיית הקליע לפני", r"הגוף במנוחה", r"\tfrac{1}{2} \cdot 0.015 \cdot 170.7^2 \approx 218.5\,\text{J}"),
        S(r"ההפרש", r"מה שנשאר אחרי ההתנגשות 0.656 J", r"218.5 - 0.66 \approx 217.9\,\text{J}"),
    ], r"$\approx 217.9\,\text{J}$", key=r"−217.88 J"),
  ],
  concepts=["מטוטלת בליסטית", "התנגשות פלסטית", "שימור תנע", "שימור אנרגיה", "אובדן אנרגיה"],
  summary=r"מטוטלת בליסטית: מזווית הסטייה מוצאים את האנרגיה, מזה את מהירות הגוף, ומשימור תנע את מהירות הקליע. כמעט כל האנרגיה אובדת.")
